{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a lung infection called pneumonia and diabetes.",
          "sources": ["p1:L5", "term:CAP", "term:DM"]
        }
      ]
    },
    {
      "title": "Your medicines",
      "bullets": [
        {
          "id": "b2",
          "text": "Azithromycin 250 mg, take once a day by mouth for 3 more days. It is an antibiotic that treats mild to moderate bacterial infections.",
          "sources": ["p1:L8", "drug:azithromycin", "term:PO"]
        },
        {
          "id": "b3",
          "text": "Acetaminophen 650 mg, take every 6 hours by mouth only when you need it for fever or pain. Do not take more than 3,000 mg in a day. It relieves minor aches, pains, and reduces fever.",
          "sources": ["p1:L9", "drug:acetaminophen", "term:q6h", "term:PRN", "term:PO"]
        },
        {
          "id": "b4",
          "text": "Metformin ER 500 mg, take once a day by mouth with dinner. It is a diabetes medicine that helps control blood sugar with diet and exercise.",
          "sources": ["p1:L10", "drug:metformin", "term:PO"]
        },
        {
          "id": "b5",
          "text": "Atorvastatin 10 mg, take once a day by mouth at bedtime. It lowers cholesterol and reduces the risk of heart attack and stroke.",
          "sources": ["p1:L11", "drug:atorvastatin", "term:QHS", "term:PO"]
        },
        {
          "id": "b6",
          "text": "Aspirin 81 mg, take once a day by mouth. It relieves minor aches and pains.",
          "sources": ["p1:L12", "drug:aspirin", "term:PO"]
        },
        {
          "id": "b7",
          "text": "Ask your doctor if you should keep taking diphenhydramine 25 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:1"]
        },
        {
          "id": "b8",
          "text": "Ask your doctor if you should keep taking naproxen 500 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:2"]
        },
        {
          "id": "b9",
          "text": "Ask your doctor if you should keep taking carbamazepine 20 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:3"]
        },
        {
          "id": "b10",
          "text": "Ask your doctor if you should keep taking metoprolol succinate 200 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:8"]
        },
        {
          "id": "b11",
          "text": "Ask your doctor if you should keep taking lisinopril 40 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:10"]
        },
        {
          "id": "b12",
          "text": "Ask your doctor if you should keep taking prasugrel 10 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:11"]
        },
        {
          "id": "b13",
          "text": "Ask your doctor if you should keep taking simvastatin 10 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:110"]
        },
        {
          "id": "b14",
          "text": "Ask your doctor if you should keep taking amlodipine 2.5 mg. It is not on your discharge paper but is in your hospital record.",
          "sources": ["record:148"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b15",
          "text": "Rest and increase activity as you can. Use your incentive spirometer 10 times each hour while you are awake.",
          "sources": ["p1:L13"]
        },
        {
          "id": "b16",
          "text": "Follow a carb-consistent diabetic diet. Drink plenty of fluids.",
          "sources": ["p1:L14"]
        },
        {
          "id": "b17",
          "text": "Follow up with your primary care doctor in 7 to 10 days.",
          "sources": ["p1:L15"]
        },
        {
          "id": "b18",
          "text": "Get a repeat chest x-ray in 6 weeks.",
          "sources": ["p1:L15"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b19",
          "text": "See your primary care doctor in 7 to 10 days.",
          "sources": ["p1:L15"]
        },
        {
          "id": "b20",
          "text": "Repeat chest x-ray in 6 weeks.",
          "sources": ["p1:L15"]
        }
      ]
    }
  ],
