  "call_911_if": [
    {
      "id": "w1",
      "text": "Call your doctor or 911 if you have trouble breathing or your lips turn blue.",
      "sources": ["p1:L16", "p1:L17"]
    },
    {
      "id": "w2",
      "text": "Call your doctor or 911 if you have a fever over 101 F after 3 days on antibiotics.",
      "sources": ["p1:L16", "p1:L18"]
    },
    {
      "id": "w3",
      "text": "Call your doctor or 911 if you have new confusion.",
      "sources": ["p1:L16", "p1:L19"]
    },
    {
      "id": "w4",
      "text": "Call your doctor or 911 if your blood sugar is over 300 twice in a row.",
      "sources": ["p1:L16", "p1:L20"]
    }
  ],
